window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0dd25a906db8dc6d"]={"versions": [{"id": "FIG-0dd25a906db8dc6d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells) zur Veranschaulichung des Modellvergleichs und der Interoperabilität von AUTOSAR-Werkzeugen bei Modelländerungen (hier: Umbenennung eines Datentyps). Das Diagramm stellt ein Beispielszenario dar, in dem ein <code>ApplicationPrimitiveDataType</code> modifiziert wurde.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende anonyme Instanzen mit Attributen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit <code>shortName = OEM</code> aggregiert über die Kompositionsrolle <code>+element</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> mit <code>shortName = speedType</code>\n</li><li><code>:SenderReceiverInterface</code> mit <code>isService = false</code>, <code>shortName = interface</code>\n</li></ul>\n</li><li><code>:ApplicationPrimitiveDataType</code> aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> mit <code>value = 10000</code>\n</li><li><code>+displayFormat</code>: <code>:DisplayFormatString</code> mit <code>value = %f6.2</code>\n</li></ul>\n</li><li><code>:SenderReceiverInterface</code> aggregiert über <code>+dataElement</code>:\n<ul class=\"fig-list\"><li><code>:VariableDataPrototype</code> mit <code>shortName = velocity</code>\n</li></ul>\n</li><li><code>:VariableDataPrototype</code> referenziert über die gerichtete Assoziation <code>+type</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (<code>shortName = speedType</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Farbkodierung: Grün hinterlegte Elemente (<code>:ARPackage</code>, <code>:ApplicationPrimitiveDataType</code>, <code>:VariableDataPrototype</code>) repräsentieren modifizierte bzw. betroffene Modellbestandteile im Differenzvergleich, beige hinterlegte Elemente (<code>:SenderReceiverInterface</code>, <code>:NumericalValueSpecification</code>, <code>:DisplayFormatString</code>) bleiben unmodifiziert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm; kein dynamischer Sequenzablauf vorhanden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient Entwicklern von AUTOSAR-Werkzeugen zur Erkennung von Modellunterschieden und Abhängigkeiten. Bei der Umbenennung eines Datentyps (<code>speedType</code>, vormals <code>velocityType</code>) muss ein Werkzeug zur Konsistenzsicherung sowohl die Aggregationen im umgebenden <code>ARPackage</code> als auch sämtliche typisierende Referenzen (hier die <code>+type</code>-Assoziation des <code>VariableDataPrototype</code>) nachführen. Die Attribute <code>invalidValue</code> und <code>displayFormat</code> hängen als Kindelemente direkt am umbenannten Typ.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-329ac452d5d59b81", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells) zur Veranschaulichung des Modellvergleichs und der Interoperabilität von AUTOSAR-Werkzeugen bei Modelländerungen (hier: Umbenennung eines Datentyps). Das Diagramm stellt ein Beispielszenario dar, in dem ein <code>ApplicationPrimitiveDataType</code> modifiziert wurde.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende anonyme Instanzen mit Attributen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit <code>shortName = OEM</code> aggregiert über die Kompositionsrolle <code>+element</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> mit <code>shortName = speedType</code>\n</li><li><code>:SenderReceiverInterface</code> mit <code>isService = false</code>, <code>shortName = interface</code>\n</li></ul>\n</li><li><code>:ApplicationPrimitiveDataType</code> aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> mit <code>value = 10000</code>\n</li><li><code>+displayFormat</code>: <code>:DisplayFormatString</code> mit <code>value = %f6.2</code>\n</li></ul>\n</li><li><code>:SenderReceiverInterface</code> aggregiert über <code>+dataElement</code>:\n<ul class=\"fig-list\"><li><code>:VariableDataPrototype</code> mit <code>shortName = velocity</code>\n</li></ul>\n</li><li><code>:VariableDataPrototype</code> referenziert über die gerichtete Assoziation <code>+type</code>:\n<ul class=\"fig-list\"><li><code>:ApplicationPrimitiveDataType</code> (<code>shortName = speedType</code>)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Farbkodierung: Grün hinterlegte Elemente (<code>:ARPackage</code>, <code>:ApplicationPrimitiveDataType</code>, <code>:VariableDataPrototype</code>) repräsentieren modifizierte bzw. betroffene Modellbestandteile im Differenzvergleich, beige hinterlegte Elemente (<code>:SenderReceiverInterface</code>, <code>:NumericalValueSpecification</code>, <code>:DisplayFormatString</code>) bleiben unmodifiziert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm; kein dynamischer Sequenzablauf vorhanden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient Entwicklern von AUTOSAR-Werkzeugen zur Erkennung von Modellunterschieden und Abhängigkeiten. Bei der Umbenennung eines Datentyps (<code>speedType</code>, vormals <code>velocityType</code>) muss ein Werkzeug zur Konsistenzsicherung sowohl die Aggregationen im umgebenden <code>ARPackage</code> als auch sämtliche typisierende Referenzen (hier die <code>+type</code>-Assoziation des <code>VariableDataPrototype</code>) nachführen. Die Attribute <code>invalidValue</code> und <code>displayFormat</code> hängen als Kindelemente direkt am umbenannten Typ.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0dd25a906db8dc6d", "to": "FIG-329ac452d5d59b81", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
